select a."FINANCIER_ID", o."ORG_NAME_AR" "FINANCIER_NAME_AR", o."ORG_TYPE_CODE", a."PROGRAM_VERSION_ID", pv."PROGRAM_CODE", a."STATUS_CODE", st."NAME_AR" "STATUS_NAME_AR", count(*) "APPLICATION_COUNT", sum(coalesce(a."REQUESTED_FINANCE_AMOUNT", 0)) "REQUESTED_FINANCE_TOTAL", sum(coalesce(a."APPROVED_FINANCE_AMOUNT", 0)) "APPROVED_FINANCE_TOTAL", sum(coalesce(a."TOTAL_SUBSIDY_AMOUNT", 0)) "SUBSIDY_TOTAL"
from "MFF_APPLICATIONS" a
join "MFF_ORGANIZATIONS" o on o."ORG_ID" = a."FINANCIER_ID"
join "MFF_PROGRAM_VERSIONS" pv on pv."PROGRAM_VERSION_ID" = a."PROGRAM_VERSION_ID"
join "MFF_LKP_APPLICATION_STATUSES" st on st."CODE" = a."STATUS_CODE"
group by a."FINANCIER_ID", o."ORG_NAME_AR", o."ORG_TYPE_CODE", a."PROGRAM_VERSION_ID", pv."PROGRAM_CODE", a."STATUS_CODE", st."NAME_AR"
